window.OmniFeature=a=>{let overlay=null,targets=[],labels=[],selected=0,prefix='',prior=null;const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZ';function visible(e){const r=e.getBoundingClientRect();return !e.disabled&&!e.closest('[hidden],[inert],[aria-hidden=true]')&&r.width>0&&r.height>0&&r.top>=0&&r.left>=0&&r.bottom<=innerHeight&&r.right<=innerWidth&&getComputedStyle(e).visibility!=='hidden'}function close(restore=true){overlay?.remove();overlay=null;targets=[];labels=[];prefix='';if(restore&&prior?.isConnected)prior.focus();prior=null}function highlight(){labels.forEach((e,i)=>e.classList.toggle('ob-hint-selected',i===selected))}function open(){close(false);prior=document.activeElement;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_ELEMENT);let node,count=0;const cap=Math.max(20,Math.min(200,Number(a.settings.get('limit'))||100));while((node=walker.nextNode())&&count++<5000&&targets.length<cap){if(node.matches('a[href],button,input:not([type=hidden]),select,textarea,[tabindex="0"]')&&visible(node))targets.push(node)}overlay=document.createElement('div');overlay.className='ob-link-hints';overlay.setAttribute('role','status');overlay.setAttribute('aria-label','Link hints active. Arrows choose, Enter activates, Escape closes.');targets.forEach((e,i)=>{const r=e.getBoundingClientRect(),label=document.createElement('span');label.className='ob-link-hint';label.textContent=alphabet[Math.floor(i/alphabet.length)]+alphabet[i%alphabet.length];label.style.left=Math.min(innerWidth-70,Math.max(0,r.left))+'px';label.style.top=Math.min(innerHeight-44,Math.max(0,r.top))+'px';labels.push(label);overlay.append(label)});document.documentElement.append(overlay);selected=0;highlight();if(!targets.length){close();a.toast('No visible controls found.').catch(()=>{})}}function activate(index){const e=targets[index];close(false);if(e?.isConnected){e.focus();if(!e.matches('input,textarea,select'))e.click()}}function key(e){if(!a.active||!e.isTrusted)return;if(e.altKey&&e.shiftKey&&e.code==='KeyL'&&!e.repeat){e.preventDefault();e.stopImmediatePropagation();overlay?close():open();return}if(!overlay||e.ctrlKey||e.metaKey||e.altKey)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter','Escape'].includes(e.key)||/^[a-z]$/i.test(e.key)){e.preventDefault();e.stopImmediatePropagation()}if(e.key==='Escape')close();else if(e.key==='Enter')activate(selected);else if(e.key.startsWith('Arrow')){selected=Math.max(0,Math.min(targets.length-1,selected+(['ArrowUp','ArrowLeft'].includes(e.key)?-1:1)));prefix='';highlight()}else if(/^[a-z]$/i.test(e.key)){prefix=(prefix+e.key.toUpperCase()).slice(-2);if(prefix.length===2){const i=labels.findIndex(x=>x.textContent===prefix);if(i>=0)activate(i);prefix=''}}}function reset(){close()}return{enable(){document.addEventListener('keydown',key,true);window.addEventListener('blur',reset);window.addEventListener('resize',reset);window.addEventListener('scroll',reset,true)},disable(){close();document.removeEventListener('keydown',key,true);window.removeEventListener('blur',reset);window.removeEventListener('resize',reset);window.removeEventListener('scroll',reset,true)}}};